const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const center = ee.Geometry.Point([-116.939238, 50.332360]);
  const region = center.buffer(60000); // 60km radius

  const date1 = '2020-12-02';
  const date2 = '2020-12-05';

  // 2. Data Acquisition - MODIS for cloud detection
  const modisCol = ee.ImageCollection('MODIS/006/MOD09GA')
    .filterBounds(region);

  // Get images for both dates
  const img1 = modisCol.filterDate(date1, ee.Date(date1).advance(1, 'day')).first();
  const img2 = modisCol.filterDate(date2, ee.Date(date2).advance(1, 'day')).first();

  // Check if images exist
  const img1Exists = img1 ? true : false;
  const img2Exists = img2 ? true : false;

  if (!img1Exists || !img2Exists) {
    console.log(`Dec 2 image exists: ${img1Exists}`);
    console.log(`Dec 5 image exists: ${img2Exists}`);
    console.log("<answer>C1</answer>");
    return;
  }

  // Function to calculate cloud percentage from MODIS state band
  function getCloudPercentage(img) {
    // Extract cloud state from state_1km band (bits 0-1: 00=clear, 01=cloudy, 10=mixed, 11=not set)
    const cloudState = img.select('state_1km').bitwiseAnd(3);
    const cloudyPixels = cloudState.eq(1); // Cloudy state
    const clearPixels = cloudState.eq(0);  // Clear state

    const totalCount = cloudyPixels.add(clearPixels).reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: 1000,
      maxPixels: 1e9
    }).get('state_1km');

    const cloudCount = cloudyPixels.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: 1000,
      maxPixels: 1e9
    }).get('state_1km');

    return [cloudCount, totalCount];
  }

  // Calculate cloud percentages
  const [cloudCount1, totalCount1] = getCloudPercentage(img1);
  const [cloudCount2, totalCount2] = getCloudPercentage(img2);

  const cloudPct1 = (cloudCount1.getInfo() / totalCount1.getInfo()) * 100;
  const cloudPct2 = (cloudCount2.getInfo() / totalCount2.getInfo()) * 100;

  // Check for valid pixels
  if (totalCount1.getInfo() === 0 || totalCount2.getInfo() === 0) {
    console.log(`Dec 2 valid pixels: ${totalCount1.getInfo()}`);
    console.log(`Dec 5 valid pixels: ${totalCount2.getInfo()}`);
    console.log("<answer>C2</answer>");
    return;
  }

  // Validate calculations
  if (isNaN(cloudPct1) || isNaN(cloudPct2) || 
      cloudPct1 < 0 || cloudPct1 > 100 || 
      cloudPct2 < 0 || cloudPct2 > 100) {
    console.log(`Dec 2 cloud %: ${cloudPct1}`);
    console.log(`Dec 5 cloud %: ${cloudPct2}`);
    console.log("<answer>C3</answer>");
    return;
  }

  // Print results and determine answer
  console.log(`Dec 2 cloud cover: ${cloudPct1.toFixed(1)}%`);
  console.log(`Dec 5 cloud cover: ${cloudPct2.toFixed(1)}%`);
  console.log(`Cloud change: ${(cloudPct2 - cloudPct1).toFixed(1)}%`);

  if (cloudPct2 > cloudPct1) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
